import{z as s,x as o,o as i,c as A,q as l,j as B,D as e,d as t,s as p,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"peg 与 D-limit 订单","description":"","frontmatter":{"title":"peg 与 D-limit 订单","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/peg-d-limit-orders.md","filePath":"quant/peg-d-limit-orders.md","lastUpdated":1791063341000}'),d={name:"quant/peg-d-limit-orders.md"};function m(D,a,g,h,u,c){const r=o("Mermaid");return i(),A("div",null,[a[2]||(a[2]=l('<h1 id="peg-与-d-limit-订单" tabindex="-1">peg 与 D-limit 订单 <a class="header-anchor" href="#peg-与-d-limit-订单" aria-label="Permalink to &quot;peg 与 D-limit 订单&quot;">​</a></h1><div class="epigraph"><p>盯住指令把档位选择外包给引擎：随全国最优或中点自动改价。IEX 的 D-limit 更进一步，在其「报价崩溃」信号触发时自动降价，试图在连续协议里给慢挂单一条制度化的撤向保护。</p><footer>—— 据 Harris, Trading and Exchanges 对盯住与展示的论述；IEX Discretionary Limit 的制度说明对照 Budish 等对过时报价的讨论</footer></div><p><a href="/quant/speed-market-quality">速度与市场质量</a>把问题收到相对延迟。缺口是订单类型层的设计回应：不改整场批量拍卖，只给挂单者一种自动跟随或自动退避的指令。Peg（盯住）随参照价移动；D-limit 在 IEX 上结合离散限价与崩溃指标。主干<a href="/quant/order-types">订单类型</a>未展开 peg。本课写这些指令如何改放置博弈，不重画簿的几何。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最优放置要求随中点与 NBBO 连续改 \\(k\\)，FIFO 下改价丧失时间优先。<span class="marginnote">BBO 是单一交易所当时「最好的买价与卖价」；NBBO 则把全国各交易所的最好报价汇总成全国最优。直觉类比：NBBO 像比价网站上全网的最低卖价与最高买价——peg 盯着它自动改价，一旦行情数据延迟，你挂的就不再是真实的最优价。</span>Peg 让交易所代劳：primary peg 贴在己方 BBO，midpoint peg 挂在中点（常需暗处或允许的亚 tick），市场 peg 贴对方。代价是：参照价过时则 peg 本身成为被狙击对象；中点 peg 把价格发现让给公开 BBO 的形成者。问题是 peg 在降低操作成本的同时，是否把被捡从用户办公室挪到引擎与行情延迟上。</p><p>D-limit：普通限价加上当 IEX 认为报价正在崩溃时自动改到更保守的价。它试图把 Foucault 被捡窗口里的「撤」写成规则，而不是比拼用户速度。有效性取决于崩溃指标是否比狙击者更早、以及是否被博弈。</p><h3 id="盯住参照是谁的价格" tabindex="-1">盯住参照是谁的价格 <a class="header-anchor" href="#盯住参照是谁的价格" aria-label="Permalink to &quot;盯住参照是谁的价格&quot;">​</a></h3><p>Peg 依赖 NBBO 或本地 BBO。<a href="/quant/nbbo-construction">NBBO 构造</a>的时钟与尺寸规则会进入 peg 的行为。保护报价不含零股时，peg 可能盯住一个对你不可成交的价格。跨市场延迟下，peg 跟着已经过时的 NBBO 走，正好把 BCS 期权写进订单手册。</p><p><span class="marginnote">Discretionary 范围（D-peg 等）允许在限价内主动吃对侧，把限价/市价阈值外包。这与本课 D-limit 的「崩溃时退避」方向相反：一个更有攻击性，一个更保守。名字都带 D，机制不要混。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 peg 写成约束：\\(p_t=\\mathrm{ref}_t+\\mathrm{offset}\\)，受用户限价箱约束。<span class="marginnote">「限价箱」是你给订单设的价格上下限：引擎虽然代你盯价改价，但改出的价不能越出这条箱线。常见误区：以为用了 peg 就能完全不管价格——参照价大幅跳动时，箱线会卡住 peg 使它停在原位，反而错过市场。</span>每次 ref 变，引擎改价，优先权按规则：有的视为新单。均衡里，无技术的人用 peg 近似 Roşu 的近端放置，有技术的人仍用自营更新抢队头。于是 peg 用户提供「慢的近端」，成为狙击的自然对手方——除非场所加颠簸或 D-limit。</p><p>经验比较：peg 成交的实现价差、被捡（成交后中点走失）、相对普通限价的寿命。IEX D-limit 的公开描述强调在崩溃信号时减少被扫。评估必须对照同期其他场所，避免把 IEX 用户结构差当成指令效应。</p>',12)),(i(),B(n,null,{default:e(()=>[p(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20Ref%5B%22NBBO%20%2F%20%E4%B8%AD%E7%82%B9%22%5D%20--%3E%20Peg%5B%22%E8%87%AA%E5%8A%A8%E6%94%B9%E4%BB%B7%22%5D%0A%20%20Peg%20--%3E%20Risk%5B%22%E5%8F%82%E7%85%A7%E8%BF%87%E6%97%B6%E5%88%99%E8%A2%AB%E6%8D%A1%22%5D%0A%20%20Crumb%5B%22%E5%B4%A9%E6%BA%83%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20DL%5B%22D-limit%20%E8%87%AA%E5%8A%A8%E9%80%80%E9%81%BF%22%5D%0A%20%20DL%20--%3E%20Prot%5B%22%E7%BC%A9%E7%9F%AD%E8%A2%AB%E6%8D%A1%E7%AA%97%2C%20%E5%A2%9E%E9%9D%9E%E6%89%A7%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"Peg 降低非执行（自动贴住市场），增加参照错误时的逆向选择。这是上一单元两项风险的订单化。D-limit 反向：信号触发时非执行升、被捡降。若信号与真的公共跳相关、与随机噪声不相关，做市的期权金下降，价差可窄；若信号滞后或可被填塞式消息骗过，则要么保护太晚，要么频繁误退避、深度闪烁。",-1)),(i(),B(n,null,{default:e(()=>[p(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22Peg%20%E8%87%AA%E5%8A%A8%E8%B4%B4%E4%BD%8F%E5%8F%82%E7%85%A7%E4%BB%B7%22%5D%20--%3E%20A%5B%22%E9%9D%9E%E6%89%A7%E8%A1%8C%E9%A3%8E%E9%99%A9%E4%B8%8B%E9%99%8D%22%5D%0A%20%20P%20--%3E%20B%5B%22%E5%8F%82%E7%85%A7%E8%BF%87%E6%97%B6%E6%97%B6%E8%A2%AB%E6%8D%A1%E4%B8%8A%E5%8D%87%22%5D%0A%20%20D%5B%22D-limit%20%E6%A3%80%E6%B5%8B%E5%88%B0%E6%8A%A5%E4%BB%B7%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20C%5B%22%E8%87%AA%E5%8A%A8%E6%94%B9%E5%88%B0%E6%9B%B4%E4%BF%9D%E5%AE%88%E7%9A%84%E4%BB%B7%22%5D%0A%20%20C%20--%3E%20E%5B%22%E8%A2%AB%E6%8D%A1%E9%A3%8E%E9%99%A9%E4%B8%8B%E9%99%8D%22%5D%0A%20%20C%20--%3E%20F%5B%22%E9%9D%9E%E6%89%A7%E8%A1%8C%E4%B8%8E%E8%AF%AF%E9%80%80%E9%81%BF%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p>对宏观形状：peg 把量钉在 ref 附近，轮廓更集中于近端；崩溃退避时近端突然空，形状出现空洞。执行算法看到的平均 peg 深度，不是压力期深度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>各所 peg 规则、费用、是否允许锁定/交叉，差异大。中点 peg 与暗池中点是亲戚，毒性问题同构。D-limit 绑定 IEX 的信号与速度颠簸，不能当成一般连续市场的插件。<span class="marginnote">速度颠簸指 IEX 对进场所的订单强制加约 350 微秒的统一延迟，让所有人慢同一拍。为什么重要：D-limit 的退避要在别人反应过来之前生效才有价值；若没有这段统一延迟，同机房的快速交易者仍能在退避完成前完成狙击。</span>把所有自动改价叫做「智能」，会忽略它们把延迟风险社会化到参照源。</p><p><span class="marginnote">用户仍要选 offset 与限价箱，放置问题没有消失，只是从 tick 选择变成对参照与信号的选择。</span></p><p>下一课把保护从指令层收到场所层：没有进场颠簸，崩溃信号再准时也跑不过同机房的吃单。Peg 与 D-limit 依赖那一段不对称时钟。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Peg 把档位外包给参照价，降低操作型非执行，但把被捡绑定在行情延迟上。</li><li>D-limit 用崩溃信号制度化退避，权衡与限价寿命选择相同。</li><li>参照时钟与 NBBO 规则是 peg 的一部分，不是外部细节。</li><li>出处：Harris, <em>Trading and Exchanges</em>；过时报价机制见 Budish, Cramton and Shim, 2015；对照本站订单类型课。</li></ul>',7))])}const P=s(d,[["render",m]]);export{_ as __pageData,P as default};
